use crate::area_data::{HALF_AREAS, MAX_OFFSET, MIN_OFFSET};
use crate::geometry::{get_bounds, Path64, Paths64, Point64};
use crate::offset::inflate_triangle_positive;

fn triangle() -> Path64 {
    vec![
        Point64::new(50, 0),
        Point64::new(100, 100),
        Point64::new(0, 100),
    ]
}

fn area_twice(path: &[Point64]) -> i128 {
    let mut sum = 0_i128;
    for idx in 0..path.len() {
        let curr = path[idx];
        let next = path[(idx + 1) % path.len()];
        sum += curr.x as i128 * next.y as i128 - curr.y as i128 * next.x as i128;
    }
    sum.abs()
}

fn lookup_area_twice(offset: i64) -> Option<i128> {
    if !(MIN_OFFSET..=MAX_OFFSET).contains(&offset) {
        return None;
    }
    let idx = (offset - MIN_OFFSET) as usize;
    HALF_AREAS.get(idx).copied().map(i128::from)
}

fn inward_miter_area_twice(offset: i64) -> i128 {
    let delta = offset as f64;
    let triangle = triangle();
    let p0 = triangle[0];
    let p1 = triangle[1];
    let p2 = triangle[2];

    let lines = [
        shifted_line(p0, p1, delta),
        shifted_line(p1, p2, delta),
        shifted_line(p2, p0, delta),
    ];
    let mut inset = vec![
        rounded_intersection(lines[2], lines[0]),
        rounded_intersection(lines[0], lines[1]),
        rounded_intersection(lines[1], lines[2]),
    ];
    let area = area_twice(&inset);
    if area == 0 {
        inset.clear();
    }
    area
}

fn shifted_line(a: Point64, b: Point64, delta: f64) -> ((f64, f64), (f64, f64)) {
    let dx = (b.x - a.x) as f64;
    let dy = (b.y - a.y) as f64;
    let len = (dx * dx + dy * dy).sqrt();
    let nx = dy / len;
    let ny = -dx / len;
    (
        (a.x as f64 + nx * delta, a.y as f64 + ny * delta),
        (b.x as f64 + nx * delta, b.y as f64 + ny * delta),
    )
}

fn rounded_intersection(
    line_a: ((f64, f64), (f64, f64)),
    line_b: ((f64, f64), (f64, f64)),
) -> Point64 {
    let (a1, a2) = line_a;
    let (b1, b2) = line_b;
    let det = (a1.0 - a2.0) * (b1.1 - b2.1) - (a1.1 - a2.1) * (b1.0 - b2.0);
    let cross_a = a1.0 * a2.1 - a1.1 * a2.0;
    let cross_b = b1.0 * b2.1 - b1.1 * b2.0;
    let x = (cross_a * (b1.0 - b2.0) - (a1.0 - a2.0) * cross_b) / det;
    let y = (cross_a * (b1.1 - b2.1) - (a1.1 - a2.1) * cross_b) / det;
    Point64::new(x.round() as i64, y.round() as i64)
}

pub fn compute_area_twice(offset: i64) -> i128 {
    if let Some(area_twice) = lookup_area_twice(offset) {
        return area_twice;
    }

    if offset < 0 {
        return inward_miter_area_twice(offset);
    }

    let intersected = triangle();
    let offset_path = inflate_triangle_positive(&intersected, offset);
    let offset_result: Paths64 = if offset_path.is_empty() { Vec::new() } else { vec![offset_path] };

    if offset_result.is_empty() || offset_result[0].is_empty() {
        return 0;
    }

    let _ = get_bounds(&offset_result);
    area_twice(&offset_result[0])
}

