fn trim_trailing_zeros(mut text: String) -> String {
    if text.contains('.') {
        while text.ends_with('0') {
            text.pop();
        }
        if text.ends_with('.') {
            text.pop();
        }
    }
    text
}

fn format_cpp_double(value: f64) -> String {
    if value == 0.0 {
        return "0".to_string();
    }

    let precision = 6_i32;
    let negative = value.is_sign_negative();
    let absolute = value.abs();
    let mut exponent = absolute.log10().floor() as i32;
    let scale = 10_f64.powi(precision - 1 - exponent);
    let rounded = (absolute * scale).round() / scale;
    exponent = rounded.log10().floor() as i32;
    let sign = if negative { "-" } else { "" };

    if exponent < -4 || exponent >= precision {
        let mantissa = rounded / 10_f64.powi(exponent);
        let body = trim_trailing_zeros(format!("{mantissa:.5}"));
        format!("{sign}{body}e{exponent:+03}")
    } else {
        let frac_digits = (precision - exponent - 1).max(0) as usize;
        format!("{sign}{}", trim_trailing_zeros(format!("{rounded:.frac_digits$}")))
    }
}

pub fn format_area_twice(area_twice: i128) -> String {
    format_cpp_double(area_twice as f64 * 0.5)
}
